enum TransactionType { TRANSFER, TOPUP, WITHDRAWAL }

// The outcome of a transaction attempt.
enum TransactionStatus { SUCCESS, REJECTED }

// Which side of a balanced ledger line this entry represents.
enum EntryType { DEBIT, CREDIT }

// A single owner's spendable balance.
class Wallet {
    private final String walletId;   // unique id
    private final String ownerName;    // display name
    private double balance;              // current spendable balance

    public Wallet(String walletId, String ownerName, double balance) {
        this.walletId = walletId;     // store id
        this.ownerName = ownerName;     // store owner
        this.balance = balance;           // store starting balance
    }

    public String getWalletId() { return walletId; }         // id getter
    public String getOwnerName() { return ownerName; }          // owner getter
    public double getBalance() { return balance; }                // balance getter
    public void adjustBalance(double amount) { balance += amount; } // add or subtract balance
}

// One balanced debit or credit line produced by a transaction.
class LedgerEntry {
    private final String entryId;         // unique id, e.g. LE1
    private final String walletId;          // which wallet this line affects
    private final String transactionId;       // which transaction produced this line
    private final EntryType entryType;           // debit or credit
    private final double amount;                    // amount of this line

    public LedgerEntry(String entryId, String walletId, String transactionId, EntryType entryType, double amount) {
        this.entryId = entryId;             // store id
        this.walletId = walletId;             // store wallet
        this.transactionId = transactionId;     // store transaction
        this.entryType = entryType;               // store debit or credit
        this.amount = amount;                       // store amount
    }

    public EntryType getEntryType() { return entryType; } // entry type getter
    public double getAmount() { return amount; }             // amount getter
}

// One transfer, top-up, or withdrawal request.
class Transaction {
    private final String transactionId;    // unique id, e.g. TXN1
    private final String idempotencyKey;     // caller-supplied dedup key
    private final String fromWalletId;         // sender, null for a top-up
    private final String toWalletId;             // receiver, null for a withdrawal
    private final double amount;                    // requested amount
    private final double fee;                         // fee charged, if any
    private final TransactionType type;                  // transfer, top-up, or withdrawal
    private TransactionStatus status;                       // success or rejected

    public Transaction(String transactionId, String idempotencyKey, String fromWalletId, String toWalletId, double amount, double fee, TransactionType type, TransactionStatus status) {
        this.transactionId = transactionId;     // store id
        this.idempotencyKey = idempotencyKey;     // store dedup key
        this.fromWalletId = fromWalletId;           // store sender
        this.toWalletId = toWalletId;                 // store receiver
        this.amount = amount;                           // store amount
        this.fee = fee;                                   // store fee
        this.type = type;                                   // store type
        this.status = status;                                 // store status
    }

    public String getTransactionId() { return transactionId; } // id getter
    public String getIdempotencyKey() { return idempotencyKey; } // key getter
    public double getAmount() { return amount; }                  // amount getter
    public double getFee() { return fee; }                          // fee getter
    public TransactionStatus getStatus() { return status; }          // status getter
}

