// Strategy interface: how much fee a transaction type charges.
interface FeeStrategy {
    double calculateFee(double amount); // returns the fee owed on this amount
}

// Peer-to-peer transfers are free.
class NoFeeStrategy implements FeeStrategy {
    @Override
    public double calculateFee(double amount) { return 0.0; } // always zero
}

// Withdrawals to an external bank charge a percentage of the amount.
class PercentageFeeStrategy implements FeeStrategy {
    private final double percentage; // e.g. 0.02 for 2 percent

    public PercentageFeeStrategy(double percentage) {
        this.percentage = percentage; // store the rate
    }

    @Override
    public double calculateFee(double amount) { return amount * percentage; } // proportional fee
}

// Observer interface: reacts to wallet lifecycle events.
interface WalletObserver {
    void onTransactionProcessed(Transaction transaction);      // a transaction succeeded
    void onTransactionRejected(String walletId, String reason);  // a transaction failed validation
    void onDuplicateDetected(String idempotencyKey);              // a retry was deduplicated
}

// Simple observer that prints events to the console.
class ConsoleWalletObserver implements WalletObserver {
    @Override
    public void onTransactionProcessed(Transaction transaction) {
        System.out.println("Transaction " + transaction.getTransactionId() + " processed: amount " + transaction.getAmount() + " fee " + transaction.getFee());
    }

    @Override
    public void onTransactionRejected(String walletId, String reason) {
        System.out.println("Transaction rejected for " + walletId + ": " + reason);
    }

    @Override
    public void onDuplicateDetected(String idempotencyKey) {
        System.out.println("Duplicate detected for idempotency key " + idempotencyKey + ", returning original result");
    }
}

