#include <string>
#include <iostream>
using namespace std;

// Strategy interface: how much fee a transaction type charges.
class FeeStrategy {
public:
    virtual double calculateFee(double amount) = 0;
    virtual ~FeeStrategy() {}
};

// Peer-to-peer transfers are free.
class NoFeeStrategy : public FeeStrategy {
public:
    double calculateFee(double amount) override { return 0.0; } // always zero
};

// Withdrawals to an external bank charge a percentage of the amount.
class PercentageFeeStrategy : public FeeStrategy {
    double percentage; // e.g. 0.02 for 2 percent

public:
    PercentageFeeStrategy(double p) : percentage(p) {} // store the rate

    double calculateFee(double amount) override { return amount * percentage; } // proportional fee
};

// Observer interface: reacts to wallet lifecycle events.
class WalletObserver {
public:
    virtual void onTransactionProcessed(const Transaction& transaction) = 0;
    virtual void onTransactionRejected(const string& walletId, const string& reason) = 0;
    virtual void onDuplicateDetected(const string& idempotencyKey) = 0;
    virtual ~WalletObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleWalletObserver : public WalletObserver {
public:
    void onTransactionProcessed(const Transaction& transaction) override {
        cout << "Transaction " << transaction.transactionId << " processed: amount " << transaction.amount << " fee " << transaction.fee << endl;
    }
    void onTransactionRejected(const string& walletId, const string& reason) override {
        cout << "Transaction rejected for " << walletId << ": " << reason << endl;
    }
    void onDuplicateDetected(const string& idempotencyKey) override {
        cout << "Duplicate detected for idempotency key " << idempotencyKey << ", returning original result" << endl;
    }
};

