// Custom exceptions for the realistic failure modes.
class InsufficientBalanceException extends RuntimeException {
    public InsufficientBalanceException(String msg) { super(msg); }
}
class WalletNotFoundException extends RuntimeException {
    public WalletNotFoundException(String msg) { super(msg); }
}
class InvalidTransactionException extends RuntimeException {
    public InvalidTransactionException(String msg) { super(msg); }
}

// The core money-movement engine tying every piece together.
class WalletService {
    private final java.util.Map<String, Wallet> wallets = new java.util.HashMap<>();                     // walletId -> Wallet
    private final java.util.Map<String, Transaction> idempotencyStore = new java.util.HashMap<>();          // idempotencyKey -> Transaction
    private final java.util.List<LedgerEntry> ledger = new java.util.ArrayList<>();                            // every ledger line ever written
    private final java.util.List<WalletObserver> observers = new java.util.ArrayList<>();                        // listeners
    private static final String EXTERNAL_BANK = "EXTERNAL_BANK";                                                    // pseudo wallet for outbound funds
    private static final String FEE_COLLECTION = "FEE_COLLECTION";                                                     // pseudo wallet for collected fees

    public WalletService() {
        wallets.put(EXTERNAL_BANK, new Wallet(EXTERNAL_BANK, "External Bank", 0.0));   // register the external sink
        wallets.put(FEE_COLLECTION, new Wallet(FEE_COLLECTION, "Fee Collection", 0.0)); // register the fee sink
    }

    public void addWallet(Wallet wallet) { wallets.put(wallet.getWalletId(), wallet); } // register a real wallet
    public void addObserver(WalletObserver observer) { observers.add(observer); }          // register a listener

    private void writeEntry(String walletId, String transactionId, EntryType type, double amount, TransactionIdFactory factory) {
        ledger.add(new LedgerEntry(factory.nextLedgerEntryId(), walletId, transactionId, type, amount)); // append one ledger line
    }

    // Moves funds between two wallets, free of fees, deduplicated by idempotency key.
    public synchronized Transaction transfer(String fromWalletId, String toWalletId, double amount, String idempotencyKey, TransactionIdFactory factory) {
        if (idempotencyStore.containsKey(idempotencyKey)) {                     // already processed this exact request
            for (WalletObserver obs : observers) obs.onDuplicateDetected(idempotencyKey); // notify
            return idempotencyStore.get(idempotencyKey);                            // return the original result untouched
        }
        if (fromWalletId.equals(toWalletId)) throw new InvalidTransactionException("Cannot transfer to the same wallet"); // reject self-transfer
        if (amount <= 0) throw new InvalidTransactionException("Amount must be positive");   // reject non-positive amount
        Wallet from = wallets.get(fromWalletId);                                                // sender
        Wallet to = wallets.get(toWalletId);                                                       // receiver
        if (from == null || to == null) throw new WalletNotFoundException("Unknown wallet");         // reject unknown wallet
        FeeStrategy feeStrategy = new NoFeeStrategy();                                                  // peer-to-peer transfers are free
        double fee = feeStrategy.calculateFee(amount);                                                    // compute fee, zero here
        if (from.getBalance() < amount + fee) {                                                              // not enough funds
            for (WalletObserver obs : observers) obs.onTransactionRejected(fromWalletId, "Insufficient balance"); // notify
            throw new InsufficientBalanceException("Not enough balance in " + fromWalletId);
        }
        String transactionId = factory.nextTransactionId();                                                    // build id
        from.adjustBalance(-amount);                                                                             // debit sender
        to.adjustBalance(amount);                                                                                  // credit receiver
        writeEntry(fromWalletId, transactionId, EntryType.DEBIT, amount, factory);                                   // ledger debit line
        writeEntry(toWalletId, transactionId, EntryType.CREDIT, amount, factory);                                      // ledger credit line
        Transaction transaction = new Transaction(transactionId, idempotencyKey, fromWalletId, toWalletId, amount, fee, TransactionType.TRANSFER, TransactionStatus.SUCCESS);
        idempotencyStore.put(idempotencyKey, transaction);                                                          // remember this key's result
        for (WalletObserver obs : observers) obs.onTransactionProcessed(transaction);                                  // notify
        return transaction; // hand back the completed transaction
    }

    // Moves funds out of a wallet to an external bank, applying a percentage fee, deduplicated by idempotency key.
    public synchronized Transaction withdraw(String walletId, double amount, String idempotencyKey, TransactionIdFactory factory) {
        if (idempotencyStore.containsKey(idempotencyKey)) {                     // already processed this exact request
            for (WalletObserver obs : observers) obs.onDuplicateDetected(idempotencyKey); // notify
            return idempotencyStore.get(idempotencyKey);                            // return the original result untouched
        }
        if (amount <= 0) throw new InvalidTransactionException("Amount must be positive"); // reject non-positive amount
        Wallet wallet = wallets.get(walletId);                                               // withdrawing wallet
        if (wallet == null) throw new WalletNotFoundException("Unknown wallet");               // reject unknown wallet
        FeeStrategy feeStrategy = new PercentageFeeStrategy(0.02);                                // withdrawals charge 2 percent
        double fee = feeStrategy.calculateFee(amount);                                              // compute fee
        if (wallet.getBalance() < amount + fee) {                                                     // not enough funds
            for (WalletObserver obs : observers) obs.onTransactionRejected(walletId, "Insufficient balance"); // notify
            throw new InsufficientBalanceException("Not enough balance in " + walletId);
        }
        String transactionId = factory.nextTransactionId();                                          // build id
        wallet.adjustBalance(-(amount + fee));                                                          // debit the full amount plus fee
        wallets.get(EXTERNAL_BANK).adjustBalance(amount);                                                  // funds leave to the external bank
        wallets.get(FEE_COLLECTION).adjustBalance(fee);                                                      // fee collected internally
        writeEntry(walletId, transactionId, EntryType.DEBIT, amount + fee, factory);                           // ledger debit line
        writeEntry(EXTERNAL_BANK, transactionId, EntryType.CREDIT, amount, factory);                             // ledger credit to external bank
        writeEntry(FEE_COLLECTION, transactionId, EntryType.CREDIT, fee, factory);                                 // ledger credit to fee collection
        Transaction transaction = new Transaction(transactionId, idempotencyKey, walletId, EXTERNAL_BANK, amount, fee, TransactionType.WITHDRAWAL, TransactionStatus.SUCCESS);
        idempotencyStore.put(idempotencyKey, transaction);                                                     // remember this key's result
        for (WalletObserver obs : observers) obs.onTransactionProcessed(transaction);                             // notify
        return transaction; // hand back the completed transaction
    }

    // Confirms the system-wide double-entry invariant: total debits equal total credits.
    public boolean verifyLedgerIntegrity() {
        double totalDebits = 0.0;                                    // running debit total
        double totalCredits = 0.0;                                     // running credit total
        for (LedgerEntry entry : ledger) {                                // scan every ledger line ever written
            if (entry.getEntryType() == EntryType.DEBIT) totalDebits += entry.getAmount();   // accumulate debits
            else totalCredits += entry.getAmount();                                             // accumulate credits
        }
        return Math.abs(totalDebits-totalCredits) < 0.0001; // true only if the books balance
    }

    public Wallet getWallet(String walletId) { return wallets.get(walletId); } // wallet lookup, used by the demo to print balances
}

