import java.util.*;

public class Main {
    public static void main(String[] args) {
        WalletService service = new WalletService();
        service.addObserver(new ConsoleWalletObserver());
        TransactionIdFactory factory = new TransactionIdFactory();

        Wallet alice = new Wallet("Alice", "Alice", 500.0);
        Wallet bob = new Wallet("Bob", "Bob", 100.0);
        service.addWallet(alice);
        service.addWallet(bob);

        service.transfer("Alice", "Bob", 200.0, "IK1", factory);
        System.out.println("After transfer: Alice=" + service.getWallet("Alice").getBalance() + " Bob=" + service.getWallet("Bob").getBalance());

        service.transfer("Alice", "Bob", 200.0, "IK1", factory);
        System.out.println("After retry: Alice=" + service.getWallet("Alice").getBalance() + " Bob=" + service.getWallet("Bob").getBalance());

        try {
            service.transfer("Alice", "Bob", 1000.0, "IK2", factory);
        } catch (InsufficientBalanceException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        service.withdraw("Bob", 100.0, "IK3", factory);
        System.out.println("After withdrawal: Bob=" + service.getWallet("Bob").getBalance());

        try {
            service.transfer("Alice", "Alice", 50.0, "IK4", factory);
        } catch (InvalidTransactionException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        System.out.println("Ledger balanced: " + service.verifyLedgerIntegrity());
    }
}

