    } catch (InsufficientBalanceException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    service.withdraw("Bob", 100.0, "IK3", factory);
    cout << "After withdrawal: Bob=" << service.getWallet("Bob").balance << endl;

    try {
        service.transfer("Alice", "Alice", 50.0, "IK4", factory);
    } catch (InvalidTransactionException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    cout << "Ledger balanced: " << (service.verifyLedgerIntegrity() ? "true" : "false") << endl;

    return 0;
}
